#include <bits/stdc++.h>
using namespace std;const int N=12,P=998244353;int x[N],y[N],a[N],b[N],c0[N];int q(int a,int n=P-2){int r=1;for(;n;n>>=1,a=1LL*a*a%P)if(n&1)r=1LL*r*a%P;return r;}int f(int n,int k){for(int i=0;i<n;i++)if(x[i]==k)return y[i];long long r=0;for(int i=0;i<n;i++){long long a0=1,b0=1;for(int j=0;j<n;j++)if(i!=j)a0=a0*(k-x[j]+P)%P,b0=b0*(x[i]-x[j]+P)%P;r=(r+y[i]*a0%P*q(b0))%P;}return r;}int h(int n,int k){memset(c0,0,sizeof c0);for(int i=0;i<n;i++){memset(a,0,sizeof a);a[0]=1;int d=0;long long z=1;for(int j=0;j<n;j++)if(i!=j){memset(b,0,sizeof b);for(int l=0;l<=d;l++)b[l]=(b[l]-1LL*a[l]*x[j]%P+P)%P,b[l+1]=(b[l+1]+a[l])%P;memcpy(a,b,sizeof a);d++;z=z*(x[i]-x[j]+P)%P;}z=1LL*y[i]*q(z)%P;for(int j=0;j<n;j++)c0[j]=(c0[j]+z*a[j])%P;}long long r=0;for(int i=n-1;i>=0;i--)r=(r*k+c0[i])%P;return r;}int main(int c,char**v){ios::sync_with_stdio(0);cin.tie(0);int R=c>1?stoi(v[1]):1000;unsigned long long s=c>2?stoull(v[2]):1;mt19937_64 g(s);while(R--){int n=g()%8+1,k=g()%20+1;for(int i=0;i<n;i++)x[i]=i+1,y[i]=g()%P;for(int i=n-1;i;i--){int j=g()%(i+1);swap(x[i],x[j]);swap(y[i],y[j]);}if(f(n,k)!=h(n,k))return cout<<"WA\n",1;}cout<<"OK\n";}
